export const LIFE_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: LIFE_EASY_FOUNDATION,
    growth: LIFE_EASY_GROWTH,
    mastery: LIFE_EASY_MASTERY
  },
  medium: {
    foundation: LIFE_MEDIUM_FOUNDATION,
    growth: LIFE_MEDIUM_GROWTH,
    mastery: LIFE_MEDIUM_MASTERY
  },
  hard: {
    foundation: LIFE_HARD_FOUNDATION,
    growth: LIFE_HARD_GROWTH,
    mastery: LIFE_HARD_MASTERY
  },
};

export function getLifeStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = LIFE_QUESTION_REGISTRY[diffKey] || LIFE_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getLifeLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getLifeStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
